"""Guard the split between authored files and whole generated files.

Only a complete machine-generated file may be exempt from the authored-file
budget, so a generated block spliced into a hand-written module is not allowed
to grow; this test keeps the generated files whole and the list of hosts that
still carry a spliced block shrinking.
"""

import fnmatch
import re
import subprocess
import unittest
from pathlib import Path

REPO = Path(__file__).resolve().parent.parent
GENERATED_GLOBS = (
    "compiler/*_gen.vow",
    "compiler/tests/*_gen.vow",
    "vow/src/skill_gen/*.rs",
)
HEADER_PREFIX = "// GENERATED by scripts/"
MAX_GENERATED_BYTES = 450_000
MARKER = re.compile(r"^\s*// GENERATE:[A-Z_]+:START\s*$", re.MULTILINE)
SOURCE_ROOTS = ("compiler/", "vow/", "vow-")

# Hosts that still carry a spliced `// GENERATE:` block. Splitting one and moving its
# block into a generated module removes it from this set; nothing may be added.
DEFERRED_HOSTS = {
    "compiler/c_emitter.vow",
    "compiler/lower.vow",
    "vow-clif-shim/src/lib.rs",
    "vow-codegen/src/cranelift_backend.rs",
    "vow-ir/src/lower/mod.rs",
    "vow-ir/src/region.rs",
    "vow-types/src/env.rs",
    "vow-verify/src/c_emitter.rs",
}


def tracked_files() -> list[str]:
    out = subprocess.run(
        ["git", "ls-files", "-z"],
        cwd=REPO,
        stdout=subprocess.PIPE,
        check=True,
    ).stdout
    return [p for p in out.decode().split("\0") if p]


def is_generated(path: str) -> bool:
    return any(fnmatch.fnmatch(path, glob) for glob in GENERATED_GLOBS)


def source_files() -> list[str]:
    return [
        p
        for p in tracked_files()
        if p.endswith((".vow", ".rs")) and p.startswith(SOURCE_ROOTS)
    ]


class GeneratedLayoutTests(unittest.TestCase):
    def test_generated_files_carry_the_header_and_stay_small(self):
        for path in (p for p in source_files() if is_generated(p)):
            data = (REPO / path).read_bytes()
            with self.subTest(path=path):
                self.assertTrue(data.startswith(HEADER_PREFIX.encode()), path)
                self.assertLessEqual(len(data), MAX_GENERATED_BYTES, path)

    def test_generated_globs_are_exempt_in_gitattributes(self):
        attributes = (REPO / ".gitattributes").read_text().splitlines()
        exempt = {
            line.split()[0] for line in attributes if "token-limit-ignore" in line
        }
        for glob in GENERATED_GLOBS:
            self.assertIn(glob, exempt)

    def test_compiler_modules_are_not_mistaken_for_tests(self):
        # `vowc test compiler/` runs every test_*.vow and *_test.vow it finds, so a
        # driver module named like `main_test.vow` would be run as a test.
        for path in tracked_files():
            parts = path.split("/")
            if len(parts) == 2 and parts[0] == "compiler" and path.endswith(".vow"):
                self.assertFalse(parts[1].endswith("_test.vow"), path)

    def test_no_new_authored_file_carries_a_spliced_block(self):
        hosts = {
            p
            for p in source_files()
            if not is_generated(p) and MARKER.search((REPO / p).read_text())
        }
        self.assertEqual(hosts - DEFERRED_HOSTS, set(), "new spliced host")

    def test_deferred_hosts_still_carry_a_block(self):
        for path in sorted(DEFERRED_HOSTS):
            with self.subTest(path=path):
                self.assertTrue(MARKER.search((REPO / path).read_text()), path)


if __name__ == "__main__":
    unittest.main()
